 5	public class ActivitySelection {
 6	    private static final Comparator<Activity> BY_FINISH_TIME =
 7	        Comparator.comparingInt(Activity::finishTime);
 8	
 9	    private ActivitySelection() {
10	    }
11	
12	    public static int activitySelection(int[] start, int[] finish) {
13	        return maximumCompatibleActivityCount(start, finish);
14	    }
15	
16	    public static int maximumCompatibleActivityCount(int[] start, int[] finish) {
17	        return new ActivitySchedule(toSortedActivities(start, finish)).countSelectedActivities();
18	    }
19	
20	    private static Activity[] toSortedActivities(int[] start, int[] finish) {
21	        validateInputs(start, finish);
22	
23	        Activity[] activities = new Activity[start.length];
24	        for (int i = 0; i < start.length; i++) {
25	            activities[i] = new Activity(start[i], finish[i]);
26	        }
27	        Arrays.sort(activities, BY_FINISH_TIME);
28	        return activities;
29	    }
30	
31	    private static void validateInputs(int[] start, int[] finish) {
32	        Objects.requireNonNull(start, "start must not be null");
33	        Objects.requireNonNull(finish, "finish must not be null");
34	
35	        if (start.length != finish.length) {
36	            throw new IllegalArgumentException("start and finish must have the same length");
37	        }
38	    }
