47	    private static final class Activity {
48	        private final int startTime;
49	        private final int finishTime;
50	
51	        private Activity(int startTime, int finishTime) {
52	            this.startTime = startTime;
53	            this.finishTime = finishTime;
54	        }
55	
56	        private int finishTime() {
57	            return finishTime;
58	        }
59	
60	        private boolean canFollow(Activity other) {
61	            return startTime > other.finishTime;
62	        }
63	
64	        @Override
65	        public String toString() {
66	            return "[" + startTime + ", " + finishTime + "]";
67	        }
68	    }
