70	    private static final class ActivitySchedule {
71	        private final Activity[] activities;
72	
73	        private ActivitySchedule(Activity[] activities) {
74	            this.activities = activities;
75	        }
76	
77	        private int countSelectedActivities() {
78	            if (activities.length == 0) {
79	                return 0;
80	            }
81	
82	            int count = 1;
83	            Activity lastSelected = activities[0];
84	
85	            // Greedily keep the earliest-finishing compatible activity.
86	            for (int i = 1; i < activities.length; i++) {
87	                Activity current = activities[i];
88	                if (current.canFollow(lastSelected)) {
89	                    count++;
90	                    lastSelected = current;
91	                }
92	            }
93	
94	            return count;
95	        }
96	    }
